import createClient from 'openapi-fetch';
import type { components, paths } from './schema.gen';

/** The typed client of the local-server API (api/openapi.yaml), generated by openapi-typescript. */
export type ApiClient = ReturnType<typeof createClient<paths>>;

/** A schema of the API, by name: `Schema<'HostInfo'>`. */
export type Schema<N extends keyof components['schemas']> = components['schemas'][N];

export interface ApiClientOptions {
  /**
   * Prefix of every request path. Empty (the default) calls the page's own origin, which is the
   * only origin the UIs may call (same origin, no CORS, req_001 D-10). Tests pass an absolute
   * origin because Node's Request needs one.
   */
  baseUrl?: string;
  /** The fetch to use; tests pass a fake. Defaults to the browser's fetch. */
  fetch?: (input: Request) => Promise<Response>;
  /**
   * Called on every 401 answer, before the caller sees the ApiError. The admin shell uses it to
   * go back to the login page when a session ends; it decides itself whether the 401 matters
   * (a wrong password on the login form is a 401 too).
   */
  onUnauthorized?: (request: Request) => void;
}

/**
 * Creates the typed API client. It sends the session cookie only to its own origin
 * (`credentials: 'same-origin'`); the cookie is HttpOnly and the UI never reads it.
 */
export function createApiClient(opts: ApiClientOptions = {}): ApiClient {
  const client = createClient<paths>({
    baseUrl: opts.baseUrl ?? '',
    credentials: 'same-origin',
    headers: { Accept: 'application/json' },
    ...(opts.fetch ? { fetch: opts.fetch } : {}),
  });
  const onUnauthorized = opts.onUnauthorized;
  if (onUnauthorized) {
    client.use({
      onResponse({ request, response }) {
        if (response.status === 401) onUnauthorized(request);
        return undefined;
      },
    });
  }
  return client;
}

/** What went wrong with a call: no valid session, any other HTTP error, or no answer at all. */
export type ApiErrorKind = 'unauthorized' | 'http' | 'network';

/**
 * A failed API call: the HTTP status, the error envelope's fields (`{"error":{"message","type",
 * "param","code"}}`) and the X-Request-Id of the answer, which the host can look up in its log.
 * A 401 has kind `unauthorized`, so the shell can return to the login page.
 */
export class ApiError extends Error {
  readonly kind: ApiErrorKind;
  readonly status: number;
  readonly code: string | null;
  readonly type: string | null;
  readonly param: string | null;
  readonly requestId: string | null;

  constructor(init: {
    kind: ApiErrorKind;
    status: number;
    message: string;
    code?: string | null;
    type?: string | null;
    param?: string | null;
    requestId?: string | null;
  }) {
    super(init.message);
    this.name = 'ApiError';
    this.kind = init.kind;
    this.status = init.status;
    this.code = init.code ?? null;
    this.type = init.type ?? null;
    this.param = init.param ?? null;
    this.requestId = init.requestId ?? null;
  }
}

function str(v: unknown): string | null {
  return typeof v === 'string' ? v : null;
}

/** Turns an answer that is not 2xx and its parsed body into an ApiError. */
export function toApiError(response: Response, body: unknown): ApiError {
  const env = (body && typeof body === 'object' ? (body as { error?: unknown }).error : undefined) as
    | Record<string, unknown>
    | undefined;
  const message =
    (env && str(env.message)) || `The server answered ${response.status}${response.statusText ? ' ' + response.statusText : ''}.`;
  return new ApiError({
    kind: response.status === 401 ? 'unauthorized' : 'http',
    status: response.status,
    message,
    code: env ? str(env.code) : null,
    type: env ? str(env.type) : null,
    param: env ? str(env.param) : null,
    requestId: response.headers.get('X-Request-Id'),
  });
}

/** Turns anything a call threw into an ApiError; a thrown fetch is a network error. */
export function asApiError(e: unknown): ApiError {
  if (e instanceof ApiError) return e;
  return new ApiError({
    kind: 'network',
    status: 0,
    message: 'The local-server host did not answer. Check that it is running.',
  });
}

export function isUnauthorized(e: unknown): boolean {
  return e instanceof ApiError && e.kind === 'unauthorized';
}

/**
 * Awaits a client call and returns its data, or throws an ApiError. Use it as
 * `const host = await call(client.GET('/admin/v1/host'))`.
 */
export async function call<T>(p: Promise<{ data?: T; error?: unknown; response: Response }>): Promise<T> {
  let res: { data?: T; error?: unknown; response: Response };
  try {
    res = await p;
  } catch (e) {
    throw asApiError(e);
  }
  if (!res.response.ok) throw toApiError(res.response, res.error);
  return res.data as T;
}
